const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let initialized=false,busy=false;
async function api(path,body){const r=await fetch('/api/budget-alerts/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})}),j=await r.json();if(!r.ok)throw new Error(j.error?.message||'请求失败');return j;}
const labels={accepted:'平台已受理',pending:'待发送',rejected:'平台拒绝',uncertain:'结果未确认',sending:'发送中或待核实'};
async function load(){try{const s=await api('status');if(!initialized){$('enabled').checked=s.enabled;$('consent').checked=s.enabled;initialized=true;}$('token').placeholder=s.configured?'已保存，留空保持不变':'未设置；请完整粘贴自己的 Token';$('test').disabled=busy||!s.configured;const last=s.history[0];$('status').textContent=`自动提醒：${s.enabled?'已开启':'未开启'}\n微信通道：${s.configured?'Token已配置':'等待配置Token'}\n已配置接收人：${s.recipientCount||0}人\n最近检查：${s.lastCheckedAt?new Date(s.lastCheckedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'等待采集'}\n最近推送：${last?labels[last.status]+' · '+last.count+'条计划 · '+new Date(last.at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'尚未推送'}${s.error?'\n'+s.error:''}`;$('status').classList.toggle('error',Boolean(s.error));$('count').textContent=s.preview.count;$('data-status').textContent=s.preview.ready?'以下来自当天完整采集；未开启时只预览。':s.preview.message;$('rows').innerHTML=s.preview.rows.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.id)} · ${esc(p.status)}</small></td><td>${p.spend.toFixed(2)} / ${p.budget.toFixed(2)}元</td><td>${(p.ratio*100).toFixed(1)}%</td><td>${labels[p.pushStatus]||'待检查'}</td></tr>`).join('')||'<tr><td colspan="4">当前没有可提醒的计划</td></tr>';}catch(e){$('status').textContent=e.message;}}
$('settings').onsubmit=async event=>{event.preventDefault();if(busy)return;busy=true;try{await api('config',{token:$('token').value,addToken:$('add-token').value,enabled:$('enabled').checked,acceptThirdParty:$('consent').checked});$('token').value='';$('add-token').value='';$('message').textContent=$('enabled').checked?'已开启，下一轮成功采集后检查并推送。':'已保存，自动提醒处于关闭状态。';}catch(e){$('message').textContent=e.message;}finally{busy=false;await load();}};
$('test').onclick=async()=>{if(busy)return;busy=true;$('test').disabled=true;try{const r=await api('test',{});$('message').textContent=r.message;}catch(e){$('message').textContent=e.message;}finally{busy=false;await load();}};
await load();setInterval(()=>{if(!busy)void load();},15000);
